SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'spezifische_ziele_formuliert', 'Spezifische Reinigungs-/Behandlungsziele durch die Aufsichtsbehörden formuliert (Straßenabflüsse)', 'boolean', NULL, false, '§6.2.2.2, §6.2.2.3', 'Plan 3: Nein = vereinfachte Bemessung nach §6.2.2.2 (A_F = 100 m²/ha A_E,b,a, h_RR ≥ 0,5 m) und Verzicht auf das Nachweisverfahren (§6.2.2.3); Ja = Bemessung und Nachweis wie im Trennsystem. Das Ausblenden der Nachweis-Arbeitsblätter A178-12…-16 ist STAGED (a178-C-4), das Gate A_F ≥ A_F_strasse STAGED (a178-G-4).', 'imported_unverified', 'Wurden durch die Aufsichtsbehörden keine spezifischen Behandlungsziele formuliert, kann die Bemessung eines Retentionsbodenfilterbeckens zur reinen Behandlung der Niederschlagsabflüsse von Verkehrsflächen stark vereinfacht entsprechend den folgenden Vorgaben erfolgen: — Bei Retentionsbodenfilterbecken zur reinen Behandlung von Straßenoberflächenwasser, die entsprechend der oben getroffenen Festlegungen bemessen sind und für die keine besonderen Reinigungsziele formuliert wurden, kann auf das Nachweisverfahren verzichtet werden.', 'attestation', NULL, NULL, 'system_type == ''strasse''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'spezifische_ziele_formuliert') AND w.code = 'A178-02' AND s.code = 'DWA-A-178';
