SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'leichtfluessigkeitsfang_vorgesehen', 'Zusätzlicher Auffangraum für Leichtflüssigkeiten gemäß RiStWag vorgesehen (Straßenentwässerung im Wasserschutzgebiet)', 'boolean', NULL, false, '§6.2.1.3', 'Plan 3: nur sichtbar für Straßenentwässerung innerhalb eines Wasserschutzgebiets (wasserschutzgebiet ≠ zone_none); außerhalb gelten die Vorgaben für das Trennsystem. Das bestehende Attest auf A178-12 (REQ-11) bleibt; die bedingte Gate-Fassung ist STAGED (a178-G-3).', 'imported_unverified', 'Bei der Straßenentwässerung gelten außerhalb von Wasserschutzgebieten die Vorgaben für das Trennsystem. Innerhalb von Wasserschutzgebieten ist zum Schutz gegen Havarien ein zusätzlicher Auffangraum für Leichtflüssigkeiten gemäß RiStWag vorzusehen.', 'attestation', NULL, NULL, 'system_type == ''strasse'' AND wasserschutzgebiet != ''zone_none''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'leichtfluessigkeitsfang_vorgesehen') AND w.code = 'A178-02' AND s.code = 'DWA-A-178';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'h_FK_min_tab', 'Erforderliche Höhe des Filterkörpers h_FK nach §6.1.4.5 (Mischsystem ≥ 0,75 m; Trennsystem und Straßenentwässerung ≥ 0,50 m)', 'number', 'm', false, '§6.1.4.5', 'Plan 3: aus dem Entwässerungssystemtyp gefüllt (locked); das Eingabefeld h_FK_required auf A178-07 bleibt — Umstellung STAGED (a178-E-1); REQ-12 auf A178-12 liest system_type / h_FK_required, die dort nicht vererbt sind (a178-X-1 / C-1).', 'imported_unverified', 'Die erforderliche Höhe des Filterkörpers beträgt im konsolidierten Zustand: l Mischsystem $h_{\mathrm{FK}} \geq 0,75 \mathrm{~m}$, 1 Trennsystem und Straßenentwässerung $h_{\mathrm{FK}} \geq 0,50 \mathrm{~m}$.', 'lookup_fill', '{"source_label":"§6.1.4.5"}'::jsonb, '{"table_code":"S6_1_4_5","role":"limit","keys":[{"column":"system_type","from_symbol":"system_type"}],"value":"h_fk_min_m"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'h_FK_min_tab') AND w.code = 'A178-02' AND s.code = 'DWA-A-178';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'teilflaechen_178', 'Teilflächen im Einzugsgebiet (A_E,b,a,i · b_R,a [· e_0])', 'json', NULL, false, '§6.2.2.1, Gl. (2), Gl. (3)', 'Plan 3: Zeilen je befestigter, angeschlossener Teilfläche; Σ A_E,b,a,i → A_E_b_a_calc (A178-04-D1), Σ (A_E,b,a,i · b_R,a [· e_0]) → B_RBF_zu_calc (A178-04-D2), Anzahl → teilflaechen_count (-D3). Ablösung des Einzelskalars A_E_b_a_i, der Handeingabe A_E_b_a und der Gl. 2 / 3 auf A178-09 STAGED (a178-D-1 / R-1); b_R,a und e_0 je Zeile statt der Skalare auf A178-06 / -07 (a178-D-2 / D-3).', 'imported_unverified', 'B_{\mathrm{RBF}, \mathrm{zu}}=\sum\left(A_{\mathrm{E}, \mathrm{~b}, \mathrm{a}, \mathrm{i}} \cdot b_{\mathrm{R}, \mathrm{a}}\right) \tag{2} — B_{\mathrm{RBF}, \mathrm{zu}}=\sum\left(A_{\mathrm{E}, \mathrm{~b}, \mathrm{a}, \mathrm{i}} \cdot b_{\mathrm{R}, \mathrm{a}} \cdot e_{0}\right) \tag{3} — \hline $A_{\mathrm{E}, \mathrm{b}, \mathrm{a}, \mathrm{i}}$ & (ha) & befestigte, angeschlossene Teilflächen im Einzugsgebiet der Retentionsbodenfilteranlage \\', 'register', '{"title":"Befestigte, angeschlossene Teilflächen A_E,b,a,i","subtitle":"Gl. (2) Trennsystem / Gl. (3) Mischsystem — je Teilfläche i eine Zeile; die Summen → A_E,b,a und B_RBF,zu","add_label":"+ Teilfläche","placement":"section","columns":[{"key":"label","label":"Teilfläche","type":"text","required":true},{"key":"a_e_b_a_i","label":"A_E,b,a,i","type":"number","unit":"ha","required":true,"min":0,"aria_label":"Befestigte, angeschlossene Teilfläche A_E,b,a,i"},{"key":"b_r_a_i","label":"b_R,a","type":"number","unit":"kg/(ha·a)","required":true,"min":0,"placeholder":"Rechenwert 530","aria_label":"Spezifisches AFS63-Jahresfrachtpotenzial b_R,a der Teilfläche"},{"key":"b_r_a_rechenwert","label":"Rechenwert b_R,a (§6.2.2.1)","type":"derived","expr":"lookup(''S6_2_RECHENWERTE'', ''b_r_a'', ''wert'')"},{"key":"abw_rechenwert","label":"b_R,a","type":"derived","expr":"if(b_r_a_i == b_r_a_rechenwert, 0, 1)","display":"badge","value_labels":{"0":"Rechenwert","1":"abweichend vom Rechenwert (Messwert / Nachweisführung)"}},{"key":"e_0_i","label":"e_0","type":"number","unit":"%","required":true,"min":0,"max":100,"visible_when":"system_type == ''misch''","aria_label":"Mittlere Jahresentlastungsrate der Vorstufe e_0 (Mischsystem)"},{"key":"b_row","label":"Fracht der Teilfläche","type":"derived","expr":"if(system_type == ''misch'', a_e_b_a_i * b_r_a_i * e_0_i / 100, a_e_b_a_i * b_r_a_i)","unit":"kg/a"}],"footer":["A_E_b_a_calc","B_RBF_zu_calc","teilflaechen_count"],"note":"Die AFS63-Zulauffracht zum Retentionsbodenfilter kann über mittlere spezifische Jahresfrachtpotenziale ( $b_{\\mathrm{R}, \\mathrm{a}}$ ), bezogen auf $A_{\\mathrm{E}, \\mathrm{b}, \\mathrm{a},}$ abgeschätzt werden. Als Rechenwert zur Vorbemessung der Bodenfilteroberfläche wird eine flächenspezifische Fracht von $b_{\\mathrm{R}, \\mathrm{a}}=530 \\mathrm{~kg} /(\\mathrm{ha} \\cdot \\mathrm{a})$ angesetzt. Bei der Zulauffrachtermittlung im Rahmen der Nachweisführung sind alle Komponenten des Entwässerungssystems zu berücksichtigen, die zu einer Frachtminderung beitragen (z. B. vorgelagerte Regenbecken, Entlastungen, Grabensysteme etc.). Mischsystem: e_0 je Teilfläche in % (Gl. 3, \\hline $e_{0}$ & (\\%) & mittlere Jahresentlastungsrate der Vorstufe \\\\); die Spalte ist im Trenn-/Straßensystem ausgeblendet. Nur vollständige Zeilen gehen in die Summen ein — eine Mischsystem-Zeile ohne e_0 fällt aus B_RBF_zu_calc (und aus A_E_b_a_calc) heraus, bis e_0 eingetragen ist. Der Rechenwert 530 kg/(ha·a) ist zur Vorbemessung anzusetzen; im Nachweis sind alle frachtmindernden Komponenten zu berücksichtigen (§6.2.2.1)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'teilflaechen_178') AND w.code = 'A178-04' AND s.code = 'DWA-A-178';
