FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'A_E_b_a_calc') AND w.code = 'A178-04' AND s.code = 'DWA-A-178';
