SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'B_RBF_zu_calc', 'B_RBF,zu — mittlere jährliche AFS63-Zulauffracht zum Retentionsbodenfilterbecken (Gl. 2 / Gl. 3 aus dem Register)', 'number', 'kg/a', false, '§6.2.2.1, Gl. (2), Gl. (3)', 'Plan 3: Ausgabe der Gleichung A178-04-D2 (sum_rows über teilflaechen_178.b_row — Gl. 2 im Trenn-/Straßensystem, Gl. 3 mit e_0 im Mischsystem, umgeschaltet über system_type); Umstellung der Gl. 2 / 3 auf A178-09 und Übergabe an A178-10 STAGED (a178-R-1 / C-5).', 'imported_unverified', 'B_{\mathrm{RBF}, \mathrm{zu}}=\sum\left(A_{\mathrm{E}, \mathrm{~b}, \mathrm{a}, \mathrm{i}} \cdot b_{\mathrm{R}, \mathrm{a}}\right) \tag{2} — B_{\mathrm{RBF}, \mathrm{zu}}=\sum\left(A_{\mathrm{E}, \mathrm{~b}, \mathrm{a}, \mathrm{i}} \cdot b_{\mathrm{R}, \mathrm{a}} \cdot e_{0}\right) \tag{3}', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'B_RBF_zu_calc') AND w.code = 'A178-04' AND s.code = 'DWA-A-178';
