SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'fremdwasser_massnahmen_geprueft', 'Fremdwasser: Sanierungsvorschläge erarbeitet und Erfolg der Maßnahmen vor der Planung geprüft (§5.2.2)', 'boolean', NULL, false, '§5.2.2', 'Plan 3: nur sichtbar, wenn ein Fremdwasserzufluss festgestellt wurde (fremdwasser_relevant); kann der Zufluss nicht beseitigt werden, sind betriebliche Maßnahmen (alternierende Beschickung hydraulisch getrennter Filterbeete) vorzusehen oder der Bau muss unterbleiben. REQ-05 (leere Bedingung) → bedingtes Gate STAGED (a178-G-7).', 'imported_unverified', 'Wird ein Fremdwasserzufluss festgestellt, sind Sanierungsvorschläge zu erarbeiten, die einen verfahrensgerechten Betrieb des Retentionsbodenfilters ermöglichen. Vor der Planung des Retentionsbodenfilters muss geprüft werden, ob die Maßnahmen erfolgreich waren. Kann ein relevanter Fremdwasserzufluss zu einem Retentionsbodenfilterbecken nicht beseitigt werden, müssen entweder betriebliche Maßnahmen vorgesehen werden (z. B. alternierende Beschickung hydraulisch getrennter Filterbeete) oder der Bau der Anlage muss unterbleiben.', 'attestation', NULL, NULL, 'fremdwasser_relevant == true', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'fremdwasser_massnahmen_geprueft') AND w.code = 'A178-05' AND s.code = 'DWA-A-178';
