SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'v_spez_grobstoff_min', 'Mindest-Sammelvolumen des Grobstoffrückhalts nach §6.2.1.2 (0,5 m³/ha A_E,b,a)', 'number', 'm³/ha', false, '§6.2.1.2', 'Plan 3: Ausgabe der Gleichung A178-07-D3 (lookup S6_LIMITS v_spez_min); Vorgabe für Trennsystem und Straßenentwässerung; REQ-10 auf A178-12 liest v_spez_grobstoff / system_type, die dort nicht vererbt sind (a178-X-1 / C-1).', 'imported_unverified', 'Gemäß 6.1.3 ist ein unbelüfteter Grobstoffrückhalt vorzusehen, der für den Rückhalt mineralischer Grobpartikel (Sand und Kies) ausgelegt ist. Das erforderliche spezifische Sammelvolumen wird auf mindestens $0,5 \mathrm{~m}^{3} / \mathrm{ha} A_{\mathrm{E}, \mathrm{b}, \mathrm{a}}$ festgelegt.', 'derived', NULL, NULL, 'system_type IN {''trenn'', ''strasse''}', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'v_spez_grobstoff_min') AND w.code = 'A178-07' AND s.code = 'DWA-A-178';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'b_krit_tab', 'b_krit — maximal zulässige AFS63-Filterflächenbelastung nach §6.2.2.1 (7 kg/(m²·a))', 'number', 'kg/(m²·a)', false, '§6.2.2.1, Gl. (9)', 'Plan 3: Ausgabe der Gleichung A178-07-D1 (lookup S6_LIMITS b_krit); das Eingabefeld b_krit bleibt (a178-D-10); REQ-19 prüft den Literalwert 7 statt b_krit (a178-G-2).', 'imported_unverified', 'Die Bemessung von Retentionsbodenfilterbecken für die Standardanwendung nutzt den Parameter AFS63. Zur Gewährleistung eines wartungsarmen Betriebs und zur Minimierung des Kolmationsrisikos wird eine maximal zulässige AFS63-Filterflächenbelastung von $b_{\text {krit }}=7 \mathrm{~kg} /\left(\mathrm{m}^{2} \cdot \mathrm{a}\right)$ festgesetzt. Bei der Bemessung beziehen sich alle konzentrations- und frachtbezogenen Angaben auf AFS63.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'b_krit_tab') AND w.code = 'A178-07' AND s.code = 'DWA-A-178';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'q_Dr_RBF_vorgabe', 'q_Dr,RBF — konstante Abflussspende für die Vorbemessung nach §6.2.2.1 (0,05 l/(s·m²), zugleich Obergrenze bei Volleinstau §6.1.4.10)', 'number', 'l/(s·m²)', false, '§6.1.4.10, §6.2.2.1', 'Plan 3: Ausgabe der Gleichung A178-07-D2 (lookup S6_2_ANHALT q_dr_rbf_vorbemessung); für die Nachweisrechnung muss die Kennlinie des geplanten Drosselorgans angesetzt werden; das Eingabefeld q_Dr_RBF (REQ-14 ≤ 0,05) bleibt (a178-D-11).', 'imported_unverified', 'Für diese Berechnung kann eine konstante Abflussspende des Drosselorgans des Retentionsbodenfilterbeckens von $q_{\mathrm{Dr}, \mathrm{RBF}}=0,05 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ gemäß 6.1.4.10 angesetzt werden. Für die nachfolgende Nachweisrechnung muss die Kennlinie des geplanten Drosselorgans angesetzt werden. — Die Drosselung des Dränabflusses dient der Einhaltung der Filtergeschwindigkeit und damit auch der Vergleichmäßigung der Filterflächenbelastung. Es ist sicherzustellen, dass bei Volleinstau des Retentionsraums die spezifische Drosselabflussspende auf $q_{\text {Dr,RBF }}=0,05 \mathrm{l} /\left(\mathrm{s} \cdot \mathrm{m}^{2}\right)$ begrenzt ist. Eine Steuerung oder Regelung des Drosselabflusses ist nicht erforderlich.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'q_Dr_RBF_vorgabe') AND w.code = 'A178-07' AND s.code = 'DWA-A-178';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'A_F_strasse', 'A_F nach §6.2.2.2 (vereinfachte Bemessung Straßenabflüsse: 100 m²/ha · A_E,b,a)', 'number', 'm²', false, '§6.2.2.2', 'Plan 3: Ausgabe der Gleichung A178-10-D1 (lookup S6_2_RECHENWERTE a_f_strasse_m2_ha · A_E_b_a); gilt, wenn keine spezifischen Behandlungsziele formuliert wurden (spezifische_ziele_formuliert auf A178-02); Gate A_F ≥ A_F_strasse STAGED (a178-G-4). Die Sichtbarkeitsregel ist bis zur Vererbung von system_type (a178-C-1) pending.', 'imported_unverified', 'Wurden durch die Aufsichtsbehörden keine spezifischen Behandlungsziele formuliert, kann die Bemessung eines Retentionsbodenfilterbeckens zur reinen Behandlung der Niederschlagsabflüsse von Verkehrsflächen stark vereinfacht entsprechend den folgenden Vorgaben erfolgen: I spezifische Bodenfilteroberfläche $A_{\mathrm{F}}=100 \mathrm{~m}^{2} / \mathrm{ha}$ angeschlossener befestigte Fläche ( $A_{\mathrm{E}, \mathrm{b}, \mathrm{a}}$ );', 'derived', NULL, NULL, 'system_type == ''strasse''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'A_F_strasse') AND w.code = 'A178-10' AND s.code = 'DWA-A-178';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'V_RR', 'V_RR — Volumen des Retentionsraums (bis Höhe Filterbeckenüberlauf)', 'number', 'm³', false, '§6.2.2.1 Schritt 4', 'Plan 3: Eingabe aus der Geometrie des Retentionsraums (Böschungsneigung nach örtlicher Situation, §6.2.2.1); Summand von V_RBF_calc (A178-11-D1).', 'imported_unverified', 'Das nutzbare Retentionsvolumen des Retentionsbodenfilterbeckens ( $V_{\text {RBF }}$ ) ergibt sich aus dem Volumen des Retentionsraums und dem nutzbaren Porenvolumen des Filterkörpers. Das Porenvolumen wird pauschal mit $15 \%$ des Filterkörpervolumens angesetzt. Die Böschungsneigung des Retentionsraums ergibt sich aus der örtlichen Situation und der konstruktiven Gestaltung.', 'scalar', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'V_RR') AND w.code = 'A178-11' AND s.code = 'DWA-A-178';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'V_FK', 'V_FK — Filterkörpervolumen', 'number', 'm³', false, '§6.2.2.1 Schritt 4', 'Plan 3: Eingabe (Bodenfilteroberfläche · Höhe des Filterkörpers im konsolidierten Zustand); 15 % davon gehen als nutzbares Porenvolumen in V_RBF_calc (A178-11-D1) ein.', 'imported_unverified', 'Das nutzbare Retentionsvolumen des Retentionsbodenfilterbeckens ( $V_{\text {RBF }}$ ) ergibt sich aus dem Volumen des Retentionsraums und dem nutzbaren Porenvolumen des Filterkörpers. Das Porenvolumen wird pauschal mit $15 \%$ des Filterkörpervolumens angesetzt. Die Böschungsneigung des Retentionsraums ergibt sich aus der örtlichen Situation und der konstruktiven Gestaltung.', 'scalar', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'V_FK') AND w.code = 'A178-11' AND s.code = 'DWA-A-178';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'V_RBF_calc', 'V_RBF — nutzbares Volumen des Retentionsbodenfilterbeckens (V_RR + 15 % · V_FK)', 'number', 'm³', false, '§6.2.2.1 Schritt 4', 'Plan 3: Ausgabe der Gleichung A178-11-D1 (V_RR + Porenvolumen 15 % des Filterkörpervolumens, lookup S6_2_RECHENWERTE); das Eingabefeld V_RBF bleibt — Ablösung STAGED (a178-D-8); die Formel ist im Arbeitsblatt in Worten beschrieben (a178-F-3).', 'imported_unverified', 'Das nutzbare Retentionsvolumen des Retentionsbodenfilterbeckens ( $V_{\text {RBF }}$ ) ergibt sich aus dem Volumen des Retentionsraums und dem nutzbaren Porenvolumen des Filterkörpers. Das Porenvolumen wird pauschal mit $15 \%$ des Filterkörpervolumens angesetzt. Die Böschungsneigung des Retentionsraums ergibt sich aus der örtlichen Situation und der konstruktiven Gestaltung.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'V_RBF_calc') AND w.code = 'A178-11' AND s.code = 'DWA-A-178';
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'rrl_vorhanden == true' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 'V_RRL' AND w.code = 'A178-11' AND s.code = 'DWA-A-178' AND f.active;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'vorstufe_typ', 'Vorstufentyp (Tabelle 1, Anmerkung 1: RKB q_A ≤ 10 m/h / RÜB-DB → η_VS = 0,2; sonst 0)', 'enum', NULL, false, '§6.2.2.3 Tab. 1 Anmerkung 1), §6.2.1.1', 'Plan 3: Treiber der Tab.-1-Fußnote (füllt eta_VS_tab1; das Eingabefeld eta_VS bleibt — Umstellung STAGED, a178-E-2). „Stauraumkanal mit unten liegender Entlastung“: die Ausnahme e_0 > 55 % im Bestand ist nicht zulässig (§6.2.1.1; Gate STAGED a178-G-6). Tokens und Beschriftungen sind Sache des Eigentümers (a178-J-1).', 'imported_unverified', '1) Bei vorhandenen RKB $\left(q_{\mathrm{A}} \leq 10 \mathrm{~m} / \mathrm{h}\right)$ oder RÜB-DB kann für AFS63 $\eta_{\mathrm{VS}}=0,2$ angesetzt werden. — Bestehende Entlastungsbauwerke können in der Regel als Vorstufe genutzt werden, wenn sie eine Entlastungsrate von $e_{0} \leq 55 \%$ einhalten und regelgerecht betrieben werden. In Einzelfällen kann im Bestand eine höhere Entlastungsrate zugelassen werden. Für Stauraumkanäle mit unten liegender Entlastung ist diese Ausnahme nicht zulässig, weil bei diesen Anlagen mit einem erhöhten Feststoffaustrag zu rechnen ist.', 'select_one', NULL, NULL, NULL, '[{"value":"rkb_le10","label_de":"Regenklärbecken RKB (q_A ≤ 10 m/h)","order_index":0},{"value":"rueb_db","label_de":"Regenüberlaufbecken als Durchlaufbecken (RÜB-DB)","order_index":1},{"value":"stauraum_unten","label_de":"Stauraumkanal mit unten liegender Entlastung","order_index":2},{"value":"sonstige","label_de":"sonstige Vorstufe (Grobstoffrückhalt, RÜB ohne DB, Stauraumkanal mit oben liegender Entlastung)","order_index":3}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'vorstufe_typ') AND w.code = 'A178-13' AND s.code = 'DWA-A-178';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'eta_VS_tab1', 'η_VS — Frachtrückhaltegrad der Vorstufe nach Tabelle 1 (0; bei RKB q_A ≤ 10 m/h oder RÜB-DB kann 0,2 angesetzt werden)', 'number', '-', false, '§6.2.2.3 Tab. 1 Anmerkung 1)', 'Plan 3: aus dem Vorstufentyp gefüllt; Policy „kann“ = Wahl zwischen den gedruckten Alternativen 0 / 0,2 (die Auswahl steht auch für Zeilen mit Basiswert 0 offen — a178-O-4); das Eingabefeld eta_VS (Gl. 5–7) bleibt — Umstellung STAGED (a178-E-2).', 'imported_unverified', '1) Bei vorhandenen RKB $\left(q_{\mathrm{A}} \leq 10 \mathrm{~m} / \mathrm{h}\right)$ oder RÜB-DB kann für AFS63 $\eta_{\mathrm{VS}}=0,2$ angesetzt werden.', 'lookup_fill', '{"source_label":"Tab. 1 Anm. 1)"}'::jsonb, '{"table_code":"TABELLE1_VS","role":"value","keys":[{"column":"vorstufe_typ","from_symbol":"vorstufe_typ"}],"value":"eta_vs"}'::jsonb, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'eta_VS_tab1') AND w.code = 'A178-13' AND s.code = 'DWA-A-178';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'frachtpfade', 'Abflusspfade der Langzeitsimulation (VQ_Dr,RBF / VQ_FÜ / VQ_Dr,RRL mit η nach Tabelle 1)', 'json', NULL, false, '§6.2.2.3, Gl. (5)–(7), Tab. 1', 'Plan 3: eine Zeile je Abflusspfad; Σ (VQ · η) · C_RBFA,zu · (1 − η_VS) / (A_F · 1.000) → b_F_calc (A178-13-D1, reproduziert Gl. 5 / 6 / 7 je nach erfassten Pfaden), Σ Frachtaustrag → B_RBF_ab_calc (-D3), Pfade außerhalb der Anlagenkonfiguration → frachtpfade_unzulaessig (-D4). Ablösung der Skalare VQ_Dr_RBF / VQ_FU / VQ_Dr_RRL / eta_RR / eta_RRL und der drei Gl.-5/6/7-Zeilen STAGED (a178-D-4 / D-5 / R-2).', 'imported_unverified', 'b_{F}=\frac{\left(V Q_{D r, R B F} \cdot \eta_{F}\right) \cdot C_{R B F A, z u} \cdot\left(1-\eta_{V S}\right)}{A_{F} \cdot 1.000} \tag{5} — b_{F}=\frac{\left(V Q_{D r, R B F} \cdot \eta_{F}+V Q_{F U} \cdot \eta_{R R}\right) \cdot C_{R B F A, z u} \cdot\left(1-\eta_{V S}\right)}{A_{F} \cdot 1.000} \tag{6} — b_{F}=\frac{\left(V Q_{D r, R B F} \cdot \eta_{F}+V Q_{F U} \cdot \eta_{R R}+V Q_{D r, R R L} \cdot \eta_{R R L}\right) \cdot C_{R B F A, z u} \cdot\left(1-\eta_{V S}\right)}{A_{F} \cdot 1.000} \tag{7}', 'register', '{"title":"Abflusspfade der Langzeitsimulation (Gl. 5 / 6 / 7)","subtitle":"je Pfad das mittlere jährliche Abflussvolumen VQ; η aus Tabelle 1; Fangfilterbecken: nur Drosselabfluss RBF — Durchlauffilterbecken: + Filterbeckenüberlauf — mit Regenrückhaltelamelle: + RRL-Drossel","add_label":"+ Abflusspfad","placement":"section","columns":[{"key":"pfad","label":"Abflusspfad","type":"enum","required":true,"options":["dr_rbf","fue","dr_rrl"],"option_labels":{"dr_rbf":"Drosselorgan des Retentionsbodenfilterbeckens (VQ_Dr,RBF · η_F)","fue":"Filterbeckenüberlauf (VQ_FÜ · η_RR)","dr_rrl":"Drosselorgan der Regenrückhaltelamelle (VQ_Dr,RRL · η_RRL)"}},{"key":"vq_m3","label":"VQ","type":"number","unit":"m³/a","required":true,"min":0,"aria_label":"Mittleres jährliches Abflussvolumen VQ des Pfads"},{"key":"eta_tab1","label":"η (Tab. 1)","type":"derived","expr":"if(pfad == ''dr_rbf'', lookup(''TABELLE1'', ''f'', ''eta_afs63''), if(pfad == ''fue'', lookup(''TABELLE1'', ''rr'', ''eta_afs63''), lookup(''TABELLE1'', ''rrl'', ''eta_afs63'')))"},{"key":"zulaessig","label":"Konfiguration","type":"derived","expr":"if(pfad == ''fue'', if(becken_typ == ''durchlauf'', 1, 0), if(pfad == ''dr_rrl'', if(rrl_vorhanden == true, 1, 0), 1))","display":"badge","value_labels":{"0":"nicht zur Anlagenkonfiguration passend (Beckentyp / RRL)","1":"zur Anlagenkonfiguration passend"}},{"key":"b_ab","label":"Frachtaustrag des Pfads","type":"derived","expr":"vq_m3 * C_RBFA_zu * (1 - eta_VS) * (1 - eta_tab1) / 1000","unit":"kg/a"}],"footer":["b_F_calc","B_RBF_ab_calc","frachtpfade_unzulaessig"],"note":"l $V Q_{\\text {RBFA,zu }}\\left(\\mathrm{m}^{3} / \\mathrm{a}\\right)$ mittleres jährliches Zuflussvolumen zur Retentionsbodenfilteranlage l $V Q_{\\mathrm{Dr}, \\mathrm{RBF}}\\left(\\mathrm{m}^{3} / \\mathrm{a}\\right)$ mittleres jährliches Abflussvolumen über das Drosselorgan des Retentionsbodenfiterbeckens I $V Q_{F \\ddot{U}} \\quad\\left(\\mathrm{~m}^{3} / \\mathrm{a}\\right) \\quad$ mittleres jährliches Abflussvolumen über den Filterbeckenüberlauf I $V Q_{\\mathrm{Dr}, \\mathrm{RRL}}\\left(\\mathrm{m}^{3} / \\mathrm{a}\\right)$ mittleres jährliches Abflussvolumen des Drosselorgans einer Regenrückhaltelamelle Die Rechenwerte η_F = 0,95 / η_RR = 0,50 / η_RRL = 0,60 (Tab. 1) sind zur Anwendung in Gl. (5) bis Gl. (7) festgelegt (locked); der nach Gl. (13) ausgewertete η_F ist eine eigene Größe (a178-R-3)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'frachtpfade') AND w.code = 'A178-13' AND s.code = 'DWA-A-178';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'b_F_calc', 'b_F — mittlere jährliche spezifische Bodenfilteroberflächenbelastung (AFS63) aus den Abflusspfaden', 'number', 'kg/(m²·a)', false, '§6.2.2.3, Gl. (5)–(7)', 'Plan 3: Ausgabe der Gleichung A178-13-D1 — die eine Zeilensumme, die Gl. 5 (nur Drosselabfluss), Gl. 6 (+ Filterbeckenüberlauf) und Gl. 7 (+ RRL-Drossel) je nach erfassten Pfaden wiedergibt; Umstellung der drei Gleichungszeilen und Übergabe an A178-16 STAGED (a178-R-2 / C-5); Prüfung 4 ≤ b_F ≤ b_krit (Gl. 9) auf b_F_calc STAGED (a178-G-5).', 'imported_unverified', 'b_{F}=\frac{\left(V Q_{D r, R B F} \cdot \eta_{F}\right) \cdot C_{R B F A, z u} \cdot\left(1-\eta_{V S}\right)}{A_{F} \cdot 1.000} \tag{5} — b_{F}=\frac{\left(V Q_{D r, R B F} \cdot \eta_{F}+V Q_{F U} \cdot \eta_{R R}\right) \cdot C_{R B F A, z u} \cdot\left(1-\eta_{V S}\right)}{A_{F} \cdot 1.000} \tag{6} — b_{F}=\frac{\left(V Q_{D r, R B F} \cdot \eta_{F}+V Q_{F U} \cdot \eta_{R R}+V Q_{D r, R R L} \cdot \eta_{R R L}\right) \cdot C_{R B F A, z u} \cdot\left(1-\eta_{V S}\right)}{A_{F} \cdot 1.000} \tag{7}', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'b_F_calc') AND w.code = 'A178-13' AND s.code = 'DWA-A-178';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'C_RBF_zu_calc', 'C_RBF,zu — mittlere Konzentration im Zulauf zum Retentionsbodenfilterbecken (C_RBFA,zu · (1 − η_VS))', 'number', 'mg/l', false, '§6.2.2.3 b), Gl. (5)–(7)', 'Plan 3: Ausgabe der Gleichung A178-13-D2 — mit η_VS = 0 gleich C_RBFA,zu nach Gl. (8), sonst die „entsprechende Abminderung“ um den Faktor (1 − η_VS), der in Gl. (5) bis (7) gedruckt ist (in Worten beschrieben, a178-F-1); das Eingabefeld C_RBF_zu auf A178-12 bleibt (a178-D-6).', 'imported_unverified', 'Wird die Wirksamkeit der Vorstufe für AFS63 mit Null angenommen, entspricht die Zulaufkonzentration zum Retentionsbodenfilterbecken $C_{\text {RBF,zu }}$ der nach GL. (8) ermittelten Zulaufkonzentration zur Retentionsbodenfilteranlage $C_{\text {RBF, zu }}$. Weist die Vorstufe einen nennenswerten Wirkungsgrad auf, muss eine entsprechende Abminderung erfolgen. — b_{F}=\frac{\left(V Q_{D r, R B F} \cdot \eta_{F}\right) \cdot C_{R B F A, z u} \cdot\left(1-\eta_{V S}\right)}{A_{F} \cdot 1.000} \tag{5}', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'C_RBF_zu_calc') AND w.code = 'A178-13' AND s.code = 'DWA-A-178';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'B_RBF_ab_calc', 'B_RBF,ab — mittlerer jährlicher Frachtaustrag aus dem Retentionsbodenfilterbecken (Σ der Abflusspfade)', 'number', 'kg/a', false, '§6.2.2.3 b), Gl. (11)', 'Plan 3: Ausgabe der Gleichung A178-13-D3 (Σ VQ · C_RBFA,zu · (1 − η_VS) · (1 − η) / 1.000 über die Pfade = Restfracht filtriert + Entlastung über den Filterbeckenüberlauf + RRL, wie zu Gl. 13 beschrieben; Pfadform in Worten, a178-F-2); die Eingabefelder B_Dr_RBF / B_FU / B_RRL / B_RBF_ab auf A178-14 bleiben (a178-D-7); B_RBFA,ab = Σ + B_VS (Gl. 11) ist STAGED (a178-R-4).', 'imported_unverified', '$B_{\text {RBF,ab }}(\mathrm{kg} / \mathrm{a})$ & \begin{tabular}{l} 
mittlerer jährlicher Frachtaustrag aus dem Retentionsbodenfilterbecken, \\
Summe aus Restfracht filtriert, Entlastung über den Filterbeckenüberlauf \\
und, wenn vorhanden, aus Regenrückhaltelamelle', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'B_RBF_ab_calc') AND w.code = 'A178-13' AND s.code = 'DWA-A-178';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'frachtpfade_unzulaessig', 'Abflusspfade außerhalb der Anlagenkonfiguration (Filterbeckenüberlauf ohne Durchlauffilterbecken, RRL-Drossel ohne Regenrückhaltelamelle)', 'number', NULL, false, '§6.2.2.3, Gl. (5)–(7)', 'Plan 3: Ausgabe der Gleichung A178-13-D4 (count_rows über frachtpfade mit zulaessig == 0, aus becken_typ und rrl_vorhanden); Gate „= 0“ STAGED (a178-G-5).', 'imported_unverified', 'Stoffliche Bodenfilteroberflächenbelastung bei Durchlauffilterbecken: — Stoffliche Bodenfilteroberflächenbelastung bei Durchlauffilterbecken mit Regenrückhaltelamelle:', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'frachtpfade_unzulaessig') AND w.code = 'A178-13' AND s.code = 'DWA-A-178';
UPDATE fields f SET widget = 'scalar', ui_config = NULL, lookup = NULL, visible_when = 'system_type == ''misch''' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE f.worksheet_template_id = w.id AND f.symbol = 't_RR_E_n1' AND w.code = 'A178-17' AND s.code = 'DWA-A-178' AND f.active;
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'iterationen', 'Iterationsschritte (A_F, h_RR, V_RBF, b_F je Schritt)', 'json', NULL, false, '§6.2.2.4', 'Plan 3: Zeilen je Iterationsschritt; Anzahl → iteration_count_calc (A178-18-D1), letzter Schritt → A_F_last / b_F_last (-D2 / -D3), erfüllte Schritte → iterationen_konvergiert (-D4). Ablösung der Einzelwerte A_F_iterated / V_RBF_iterated / b_F_iterated / iteration_count / convergence_achieved STAGED (a178-D-9).', 'imported_unverified', 'Entsprechen die Nachweisgrößen nicht den vorgegebenen Zielgrößen, erfolgt eine Iteration, bei der die Bodenfilteroberfläche $A_{\mathrm{F}}$ und/oder die Einstauhöhe $h_{\mathrm{RR}}$ so lange variiert werden, bis alle Vorgaben und Nachweise erfüllt sind.', 'register', '{"title":"Iterationsschritte (§6.2.2.4)","subtitle":"A_F und/oder h_RR so lange variieren, bis alle Vorgaben und Nachweise erfüllt sind — je Schritt eine Zeile (Reihenfolge = Eingabereihenfolge)","add_label":"+ Iterationsschritt","placement":"section","columns":[{"key":"schritt","label":"Schritt","type":"number","required":true,"min":1},{"key":"a_f","label":"A_F","type":"number","unit":"m²","required":true,"min":0,"aria_label":"Bodenfilteroberfläche A_F im Iterationsschritt"},{"key":"h_rr","label":"h_RR","type":"number","unit":"m","min":0,"aria_label":"Einstauhöhe h_RR im Iterationsschritt"},{"key":"v_rbf","label":"V_RBF","type":"number","unit":"m³","min":0,"aria_label":"Nutzbares Volumen V_RBF im Iterationsschritt"},{"key":"b_f","label":"b_F","type":"number","unit":"kg/(m²·a)","required":true,"min":0,"aria_label":"Bodenfilteroberflächenbelastung b_F im Iterationsschritt"},{"key":"konvergiert","label":"alle Vorgaben und Nachweise erfüllt","type":"boolean"}],"footer":["iteration_count_calc","A_F_last","b_F_last","iterationen_konvergiert"],"note":"Entsprechen die Nachweisgrößen nicht den vorgegebenen Zielgrößen, erfolgt eine Iteration, bei der die Bodenfilteroberfläche $A_{\\mathrm{F}}$ und/oder die Einstauhöhe $h_{\\mathrm{RR}}$ so lange variiert werden, bis alle Vorgaben und Nachweise erfüllt sind. Der letzte vollständige Schritt (Eingabereihenfolge) liefert A_F_last / b_F_last."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'iterationen') AND w.code = 'A178-18' AND s.code = 'DWA-A-178';
