SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'betriebsbefunde', 'Betriebsbefunde der Sichtkontrolle (Tabelle 2: Bereich · Befund · Hinweis auf)', 'json', NULL, false, '§8.3.1, Tab. 2', 'Plan 3: Zeilen je Befund mit Bereich und Hinweis aus Tabelle 2 (anhaltswert); Anzahl → befunde_count (A178-18-D5). Tabelle 2 hatte bisher kein Feldziel.', 'imported_unverified', 'Durch eine regelmäßige Begehung des Retentionsbodenfilterbeckens können anhand von einfachen Indikatoren wertvolle Hinweise zum Betriebszustand der Anlage und zur Minderung betrieblicher Risiken gewonnen werden (siehe Tabelle 2). Weitere Hinweise sind in Arbeitsblatt DWA-A 147 enthalten. — \hline \multirow[t]{5}{*}{Schilf} & üppiger Wuchs auf der gesamten Filterfläche & hohe, gleichmäßige Filterbelastung \\', 'register', '{"title":"Sichtkontrolle — einfache Indikatoren (Tabelle 2)","subtitle":"§8.3.1 — je Begehung und Befund eine Zeile; der Hinweis auf den Betriebszustand kommt aus Tabelle 2","add_label":"+ Befund","placement":"section","columns":[{"key":"datum","label":"Datum der Begehung","type":"date"},{"key":"befund","label":"Befund","type":"lookup_key","required":true,"lookup":{"table_code":"TABELLE2","group_by":"group_label"}},{"key":"bereich","label":"Bereich","type":"lookup_value","lookup":{"table_code":"TABELLE2","key_column":"befund","value":"bereich"}},{"key":"hinweis","label":"Hinweis auf","type":"lookup_value","lookup":{"table_code":"TABELLE2","key_column":"befund","value":"hinweis"}},{"key":"bemerkung","label":"Bemerkung / Maßnahme","type":"text"}],"footer":["befunde_count"],"note":"Durch eine regelmäßige Begehung des Retentionsbodenfilterbeckens können anhand von einfachen Indikatoren wertvolle Hinweise zum Betriebszustand der Anlage und zur Minderung betrieblicher Risiken gewonnen werden (siehe Tabelle 2). Weitere Hinweise sind in Arbeitsblatt DWA-A 147 enthalten."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'betriebsbefunde') AND w.code = 'A178-18' AND s.code = 'DWA-A-178';
