SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'befunde_count', 'Anzahl der erfassten Betriebsbefunde', 'number', NULL, false, '§8.3.1', 'Plan 3: Ausgabe der Gleichung A178-18-D5 (count_rows über betriebsbefunde).', 'imported_unverified', 'Durch eine regelmäßige Begehung des Retentionsbodenfilterbeckens können anhand von einfachen Indikatoren wertvolle Hinweise zum Betriebszustand der Anlage und zur Minderung betrieblicher Risiken gewonnen werden (siehe Tabelle 2). Weitere Hinweise sind in Arbeitsblatt DWA-A 147 enthalten.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'befunde_count') AND w.code = 'A178-18' AND s.code = 'DWA-A-178';
